public sealed class Wiersz {
    public long Piksele {get{return MetadanePodgladu==null?0:(long)MetadanePodgladu.Szerokosc*MetadanePodgladu.Wysokosc;}}
    public double Sekundy {get{return MetadanePodgladu==null||!MetadanePodgladu.Czas.HasValue?0:MetadanePodgladu.Czas.Value.TotalSeconds;}}
    public string WymiaryTekst {get{return Piksele==0?"—":MetadanePodgladu.Szerokosc+" × "+MetadanePodgladu.Wysokosc;}}
    public string CzasTekst {get{return Sekundy==0?"—":TimeSpan.FromSeconds(Sekundy).ToString();}}
    public string SymbolSzczegolow {get{return Rodzaj=="folder"?"\uE8B7":TypTekst=="Film"?"\uE714":TypTekst=="Zdjęcie"?"\uE91B":TypTekst=="Audio"?"\uE8D6":"\uE8A5";}}
    public string TagiKrotkie {get{var tagi=(Oznaczenia??"").Split(new[]{" · "},StringSplitOptions.RemoveEmptyEntries);return String.Join(" · ",tagi.Take(2).Select(t=>System.Globalization.CultureInfo.GetCultureInfo("pl-PL").TextInfo.ToTitleCase(t.ToLowerInvariant())))+(tagi.Length>2?" · +"+(tagi.Length-2):"");}}
    public DateTime? Utworzenie {get;set;} public long Kopie {get;set;} public long Kandydaci {get;set;} public bool Przyklad {get;set;}
    public bool WIndeksie; public string BladOdczytu; public DateTime? Dostep; public FileAttributes? Atrybuty; public MetadaneKafelka MetadanePodgladu;
    public BitmapSource PrzykladowaMiniatura {get;set;}
    public string UtworzenieTekst {get{return Utworzenie.HasValue?Utworzenie.Value.ToString("yyyy-MM-dd"):"Brak danych";}}
    public string Rozszerzenie {get{return Rodzaj=="plik"?Path.GetExtension(Sciezka).TrimStart('.').ToUpperInvariant():"";}}
    public string TypTekst {get{return Kafelki.Kategoria(this);}}
    public string StatusDuplikatu {get{return Kopie>1?"⧉ "+Kopie+" · SHA-256":Kandydaci>1?"?⧉ "+Kandydaci+" · rozmiar":Rodzaj=="folder"&&Duplikaty>0?"Grupy w poddrzewie":"—";}}
    public string Nazwa {get;set;} public string Sciezka {get;set;} public string Rodzaj {get;set;} public string Hash {get;set;}
    public long Rozmiar {get;set;} public long Pliki {get;set;} public long Podfoldery {get;set;} public double Zmiana {get;set;}
    public long[] Typy=new long[5]; public long Duplikaty; public bool Sygnal; public bool Systemowy; public string Uwagi=""; public long Grupa; public long Potencjal; public long Zajete; public long Niepewne;
    public string Oznaczenia {get;set;}
    public string RozmiarTekst {get{return Program.Rozmiar(Rozmiar);}}
    public string PlikiTekst {get{return Pliki<0?"—":Pliki.ToString("N0");}}
    public string PodfolderyTekst {get{return Podfoldery<0?"—":Podfoldery.ToString("N0");}}
    public string DataTekst {get{return Program.Data(Zmiana);}}
    public string PotencjalTekst {get{return Program.Rozmiar(Potencjal);}}
    public string ZajeteTekst {get{return Program.Rozmiar(Zajete);}}
}
public static class Program {
    public static ResourceDictionary Zasoby; public static string Katalog=AppDomain.CurrentDomain.BaseDirectory; public static string Indeks; public static string KatalogAudytu; public static Konfiguracja Ustawienia;
    public static JavaScriptSerializer Json=new JavaScriptSerializer {MaxJsonLength=int.MaxValue};
    public static readonly string KolumnyFolderu="sciezka,nazwa,rozmiar,pliki,podfoldery,zmiana,filmy,zdjecia,dokumenty,archiwa,inne,duplikaty,sygnal,systemowy,uwagi";
    public static readonly DateTime Epoka=new DateTime(1970,1,1,0,0,0,DateTimeKind.Utc);
    public static string Rozmiar(long liczba){if(liczba<0)return "Nie przeskanowano";string[] jednostki={"B","KiB","MiB","GiB","TiB"};double wartosc=liczba;int i=0;while(wartosc>=1024&&i<4){wartosc/=1024;i++;}return wartosc.ToString(i==0?"N0":"N2")+" "+jednostki[i];}
    public static string Data(double czas){return czas<=0?"Brak danych":Epoka.AddSeconds(czas).ToLocalTime().ToString("yyyy-MM-dd HH:mm");}
    public static string Prefiks(string sciezka){return sciezka.TrimEnd('\\').Replace("^","^^").Replace("%","^%").Replace("_","^_")+"\\%";}
    public static Brush Kolor(string kolor){return (Brush)new BrushConverter().ConvertFromString(kolor);}
    public static TextBlock Tekst(string tekst,int wielkosc,string kolor){return new TextBlock {Text=tekst,FontSize=wielkosc,Foreground=Kolor(kolor),TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,4,0,4)};}
    public static Button Przycisk(string tekst,Action akcja){var przycisk=new Button {Content=tekst,Margin=new Thickness(3),Padding=new Thickness(10,7,10,7),Background=Kolor("#26354A"),Foreground=Brushes.White,BorderBrush=Kolor("#41536D")};przycisk.Click+=(s,e)=>akcja();return przycisk;}
    public static Wiersz Folder(object[] r){var w=new Wiersz {Sciezka=(string)r[0],Nazwa=(string)r[1],Rozmiar=Convert.ToInt64(r[2]),Pliki=Convert.ToInt64(r[3]),Podfoldery=Convert.ToInt64(r[4]),Zmiana=Convert.ToDouble(r[5]),Duplikaty=Convert.ToInt64(r[11]),Sygnal=Convert.ToInt64(r[12])!=0,Systemowy=Convert.ToInt64(r[13])!=0,Uwagi=Convert.ToString(r[14]),Rodzaj="folder",WIndeksie=true};for(int i=0;i<5;i++)w.Typy[i]=Convert.ToInt64(r[i+6]);w.Oznaczenia=Tagi(w);return w;}
    public static Wiersz Plik(object[] r){return new Wiersz {Sciezka=(string)r[0],Nazwa=Path.GetFileName((string)r[0]),Rozmiar=Convert.ToInt64(r[1]),Zmiana=Convert.ToDouble(r[2]),Rodzaj="plik",WIndeksie=true,Hash=Convert.ToString(r[4]),Oznaczenia=Convert.ToString(r[3])};}
    public static Wiersz Grupa(object[] r){return new Wiersz {Grupa=Convert.ToInt64(r[0]),Hash=(string)r[1],Nazwa="Identyczna zawartość · "+((string)r[1]).Substring(0,12),Sciezka="SHA-256: "+r[1],Rozmiar=Convert.ToInt64(r[2]),Pliki=Convert.ToInt64(r[3]),Zajete=Convert.ToInt64(r[5]),Potencjal=Convert.ToInt64(r[6]),Niepewne=Convert.ToInt64(r[7]),Rodzaj="duplikat",Oznaczenia=Convert.ToInt64(r[7])>0?"TOŻSAMOŚĆ DO WERYFIKACJI":"POTWIERDZONY SHA-256"};}
    public static string Tagi(Wiersz w){var tagi=new List<string>();if(w.Systemowy)tagi.Add("SYSTEMOWY — NIE RUSZAĆ");if(w.Rozmiar<0)tagi.Add("NIEPRZESKANOWANY");if(w.Rozmiar>=Ustawienia.bardzoDuzyFolderGiB*1073741824L)tagi.Add("BARDZO DUŻY");else if(w.Rozmiar>=Ustawienia.duzyFolderGiB*1073741824L)tagi.Add("DUŻY FOLDER");if(Regex.IsMatch(w.Nazwa,@"telefon|fona|redmi|samsung|dcim|camera|zgryw",RegexOptions.IgnoreCase))tagi.Add("ZGRYW TELEFONU");if(w.Sygnal)tagi.Add("BACKUP / ARCHIWUM");if(w.Rozmiar>0&&w.Typy[0]>w.Rozmiar*0.6)tagi.Add("DUŻO FILMÓW");if(w.Rozmiar>0&&w.Typy[1]>w.Rozmiar*0.6)tagi.Add("DUŻO ZDJĘĆ");if(w.Duplikaty>0)tagi.Add("POTENCJALNE DUPLIKATY");if(w.Zmiana>0&&Epoka.AddSeconds(w.Zmiana)<DateTime.UtcNow.AddDays(-Ustawienia.stareDaneDni))tagi.Add("STARE DANE");if(!String.IsNullOrEmpty(w.Uwagi))tagi.Add("WYMAGA UWAGI");if(w.Sygnal||w.Duplikaty>0)tagi.Add("DO PRZEJRZENIA");return String.Join(" · ",tagi);}
    public static void Eksplorator(string sciezka){try{if(!Regex.IsMatch(sciezka,@"^[a-zA-Z]:\\"))throw new InvalidOperationException("Wymagana jest pełna ścieżka lokalna.");string folder=sciezka;if(!Directory.Exists(folder))throw new IOException("Folder nie jest obecnie dostępny. Indeks jest zapisem audytu.");if(folder.EndsWith("\\"))folder+=".";Process.Start(new ProcessStartInfo(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),"explorer.exe"),"\""+folder+"\""){UseShellExecute=true});}catch(Exception blad){MessageBox.Show(blad.Message,"Otwieranie folderu");}}
    public static void Kopiuj(string sciezka){try{Clipboard.SetText(sciezka);}catch(Exception blad){MessageBox.Show(blad.Message,"Schowek");}}
    [STAThread] public static int Main(string[] argumenty){AppDomain.CurrentDomain.UnhandledException+=(s,e)=>File.WriteAllText(Path.Combine(Katalog,"blad-krytyczny.log"),Convert.ToString(e.ExceptionObject),Encoding.UTF8);try{
        Ustawienia=Json.Deserialize<Konfiguracja>(File.ReadAllText(Path.Combine(Katalog,"konfiguracja.json"),Encoding.UTF8));Ustawienia.rozmiarStrony=Math.Max(25,Math.Min(500,Ustawienia.rozmiarStrony));
        if(String.IsNullOrWhiteSpace(Ustawienia.plikBazy)||Path.IsPathRooted(Ustawienia.plikBazy))throw new InvalidOperationException("Ścieżka bazy musi być względna względem katalogu aplikacji.");
        Indeks=Path.GetFullPath(Path.Combine(Katalog,Ustawienia.plikBazy));if(!Indeks.StartsWith(Path.GetFullPath(Katalog).TrimEnd('\\')+"\\",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Baza aplikacji musi być osobną kopią w jej katalogu. Oryginalne bazy poza aplikacją są chronione.");
        KatalogAudytu="";string plikPochodzenia=Path.Combine(Katalog,"dane","pochodzenie.json");
        if(File.Exists(plikPochodzenia)){var pochodzenie=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(plikPochodzenia,Encoding.UTF8));KatalogAudytu=Path.GetFullPath(Path.Combine(Katalog,Convert.ToString(pochodzenie["katalog_wynikow_audytu"])));if(Indeks.Equals(Path.GetFullPath(Path.Combine(Katalog,Convert.ToString(pochodzenie["oryginalny_indeks"]))),StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Oryginalny indeks audytu jest chroniony. Użyj osobnej kopii aplikacji.");}
        if(!File.Exists(Indeks))Baza.UtworzPustyIndeks(Indeks);
        if(argumenty.Length>0&&argumenty[0]=="--test"){SprawdzIndeks();return 0;}
        if(argumenty.Length>0&&argumenty[0]=="--testy"){Testy.Uruchom();return 0;}
        if(argumenty.Length>1&&(argumenty[0]=="--test-skan"||argumenty[0]=="--test-anuluj")){var token=new CancellationTokenSource();bool anuluj=argumenty[0]=="--test-anuluj";try{var wynik=Skaner.Skanuj(argumenty[1],true,token.Token,s=>{if(anuluj)token.Cancel();});File.WriteAllText(Path.Combine(Katalog,"test-skan.json"),Json.Serialize(wynik),Encoding.UTF8);}catch(OperationCanceledException){if(!anuluj)throw;File.WriteAllText(Path.Combine(Katalog,"test-anuluj.json"),"{\"anulowano\":true}",Encoding.UTF8);}return 0;}
        var aplikacja=new Application();aplikacja.ShutdownMode=ShutdownMode.OnMainWindowClose;SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(Dispatcher.CurrentDispatcher));
        var okno=new OknoGlowne();aplikacja.MainWindow=okno.Okno;
        aplikacja.DispatcherUnhandledException+=(s,e)=>{File.AppendAllText(Path.Combine(Katalog,"bledy.log"),DateTime.UtcNow.ToString("o")+" "+e.Exception+Environment.NewLine);if(argumenty.Length==0)MessageBox.Show(e.Exception.Message,"Mapa dysków — błąd");e.Handled=true;};
        if(argumenty.Length>1&&argumenty[0]=="--zrzuty"){aplikacja.DispatcherUnhandledException+=(s,e)=>{throw new InvalidOperationException("Test UI",e.Exception);};okno.ZapiszZrzuty(argumenty[1]);return 0;}
        aplikacja.Run(okno.Okno);return 0;
    }catch(Exception blad){File.WriteAllText(Path.Combine(Katalog,"blad-uruchomienia.log"),blad.ToString(),Encoding.UTF8);if(argumenty.Length==0)MessageBox.Show(blad.Message,"Nie można uruchomić Mapy dysków");return 1;}}
    static void SprawdzIndeks(){using(var baza=new Baza(Indeks,false)){var wynik=new Dictionary<string,object>();wynik["pliki"]=baza.Wartosc("SELECT count(*) FROM pliki");wynik["foldery"]=baza.Wartosc("SELECT count(*) FROM widok_folderow");wynik["duplikaty"]=baza.Wartosc("SELECT count(*) FROM grupy_duplikatow");wynik["potencjal"]=baza.Wartosc("SELECT sum(potencjal) FROM grupy_duplikatow");var zegar=Stopwatch.StartNew();var wiersze=baza.Zapytaj("SELECT "+KolumnyFolderu+" FROM widok_folderow WHERE systemowy=0 ORDER BY rozmiar DESC LIMIT 200");wynik["czas_strony_ms"]=zegar.ElapsedMilliseconds;wynik["wiersze_strony"]=wiersze.Count;wynik["pierwszy_folder"]=wiersze.Count==0?null:Folder(wiersze[0]).Sciezka;wynik["integralnosc"]=baza.Wartosc("PRAGMA quick_check");if(Convert.ToString(wynik["integralnosc"])!="ok")throw new Exception("Niepoprawny indeks.");File.WriteAllText(Path.Combine(Katalog,"test-indeks.json"),Json.Serialize(wynik),Encoding.UTF8);}}
}
public sealed partial class OknoGlowne {
    public Window Okno;DataGrid lista;TreeView drzewo;ListBox sekcje;StackPanel szczegoly;TextBox szukaj,sciezkaWidoku;TextBlock naglowek,stan,numer,opis;CheckBox systemowe;Button poprzednia,nastepna;DispatcherTimer opoznienie;int strona,wersja;string tryb="Największe foldery",folder="";bool zajety,gotowe;HashSet<int> stronyLokalizacji=new HashSet<int>();CancellationTokenSource anulowanie;List<Wiersz> ostatnie=new List<Wiersz>();
    string[] nazwySekcji={"Największe foldery","Największe pliki","Zgrywy telefonów","Filmy","Zdjęcia","Archiwa i backupy","Potwierdzone duplikaty","Foldery wymagające uwagi","Potencjalnie odzyskiwane miejsce"};
    [DllImport("dwmapi.dll")] static extern int DwmSetWindowAttribute(IntPtr okno,int atrybut,ref int wartosc,int rozmiar);
    public OknoGlowne(){using(var strumien=Assembly.GetExecutingAssembly().GetManifestResourceStream("Interfejs.xaml"))Okno=(Window)XamlReader.Load(strumien);Program.Zasoby=Okno.Resources;lista=Kontrolka<DataGrid>("Lista");drzewo=Kontrolka<TreeView>("Drzewo");sekcje=Kontrolka<ListBox>("Sekcje");szczegoly=Kontrolka<StackPanel>("Szczegoly");szukaj=Kontrolka<TextBox>("Szukaj");sciezkaWidoku=Kontrolka<TextBox>("SciezkaWidoku");naglowek=Kontrolka<TextBlock>("Naglowek");stan=Kontrolka<TextBlock>("Stan");numer=Kontrolka<TextBlock>("NumerStrony");opis=Kontrolka<TextBlock>("OpisWidoku");systemowe=Kontrolka<CheckBox>("PokazSystemowe");poprzednia=Kontrolka<Button>("Poprzednia");nastepna=Kontrolka<Button>("Nastepna");
        sekcje.ItemsSource=nazwySekcji;systemowe.IsChecked=Program.Ustawienia.domyslniePokazSystemowe;sekcje.SelectionChanged+=(s,e)=>{if(!gotowe||przywracanie||sekcje.SelectedItem==null)return;if(edycjaNazwy!=null&&!ZatwierdzNazwe())return;ZapamietajStan();tryb=Convert.ToString(sekcje.SelectedItem);folder="";strona=0;historia.Dodaj(StanWidoku());PrzyciskiHistorii();OdswiezListe();};
        opoznienie=new DispatcherTimer {Interval=TimeSpan.FromMilliseconds(350)};opoznienie.Tick+=(s,e)=>{opoznienie.Stop();strona=0;OdswiezListe();};szukaj.TextChanged+=(s,e)=>{if(gotowe){opoznienie.Stop();opoznienie.Start();}};
        systemowe.Click+=(s,e)=>{strona=0;OdswiezListe();};poprzednia.Click+=(s,e)=>{if(strona>0){strona--;OdswiezListe();}};nastepna.Click+=(s,e)=>{strona++;OdswiezListe();};
        lista.SelectionChanged+=(s,e)=>{var wybrany=lista.SelectedItem as Wiersz;PokazInformacjeZaznaczenia();};lista.MouseDoubleClick+=(s,e)=>{var w=lista.SelectedItem as Wiersz;if(w==null)return;if(w.Rodzaj=="folder")OtworzFolder(w.Sciezka);else if(w.Rodzaj=="duplikat")Porownaj(w);else OtworzElement(w);};

        Kontrolka<Button>("PorownajWybrane").Click+=(s,e)=>PorownajWybrany();Kontrolka<Button>("Odswiez").Click+=(s,e)=>OknoSkanowania();
        Okno.SourceInitialized+=(s,e)=>{int wartosc=1;try{DwmSetWindowAttribute(new WindowInteropHelper(Okno).Handle,20,ref wartosc,4);}catch{}};
        Okno.Closing+=(s,e)=>{if(zajety){if(MessageBox.Show("Przerwać skan i zamknąć aplikację? Nieukończony zakres zostanie wycofany w indeksie.","Trwa skan",MessageBoxButton.YesNo)!=MessageBoxResult.Yes){e.Cancel=true;return;}if(anulowanie!=null)anulowanie.Cancel();}};
        PrzygotujKafelki();ZaladujDyski();PrzygotujNawigacje();gotowe=true;sekcje.SelectedIndex=0;
    }
    T Kontrolka<T>(string nazwa) where T:class{return Okno.FindName(nazwa) as T;}
    public void OtworzFolder(string sciezka){Nawiguj(sciezka);}
    async void ZaladujDyski(){try{var dyski=await Task.Run(()=>DriveInfo.GetDrives().Where(d=>d.DriveType==DriveType.Fixed||d.DriveType==DriveType.Removable).Select(d=>d.Name).ToArray());drzewo.Items.Clear();foreach(string sciezka in dyski)drzewo.Items.Add(Wezel(sciezka,sciezka.TrimEnd('\\'),false));}catch(Exception blad){stan.Text=blad.Message;}}
    TreeViewItem Wezel(string sciezka,string nazwa,bool systemowy){var wezel=new TreeViewItem {Header=nazwa,Tag=sciezka,Foreground=Program.Kolor(systemowy?"#7E8899":"#CAD4E5"),ToolTip=sciezka};wezel.Items.Add(new TreeViewItem {Header="Ładowanie…",Tag=null});wezel.Expanded+=async(s,e)=>{if(e.OriginalSource!=wezel)return;if(wezel.Items.Count==1&&((TreeViewItem)wezel.Items[0]).Tag==null){wezel.Items.Clear();await DzieciDrzewa(wezel,sciezka,0);}};wezel.Selected+=(s,e)=>{if(e.OriginalSource==wezel){OtworzFolder(sciezka);e.Handled=true;}};return wezel;}
    async Task DzieciDrzewa(TreeViewItem wezel,string sciezka,int od){try{var dzieci=await Task.Run(()=>new DirectoryInfo(sciezka).EnumerateDirectories().OrderBy(d=>d.Name,StringComparer.CurrentCultureIgnoreCase).Skip(od).Take(201).Select(d=>new object[]{d.FullName,d.Name,0}).ToList());foreach(var r in dzieci.Take(200))wezel.Items.Add(Wezel((string)r[0],(Convert.ToInt64(r[2])!=0?"🔒 ":"")+(string)r[1],Convert.ToInt64(r[2])!=0));if(dzieci.Count>200){var wiecej=new TreeViewItem {Header="Pokaż kolejne 200…"};wiecej.Selected+=async(s,e)=>{e.Handled=true;wezel.Items.Remove(wiecej);await DzieciDrzewa(wezel,sciezka,od+200);};wezel.Items.Add(wiecej);}}catch(Exception blad){stan.Text=blad.Message;}}
    bool WidokDuplikatow(){return tryb=="Potwierdzone duplikaty"||tryb=="Potencjalnie odzyskiwane miejsce";}
    void Kolumny(){WczytajUklad();if(!WidokDuplikatow()){ZbudujSzczegoly();return;}lista.RowHeight=48;lista.Columns.Clear();var szablon=(DataTemplate)XamlReader.Parse("<DataTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation'><StackPanel><TextBlock Text='{Binding Nazwa}' FontWeight='SemiBold' TextTrimming='CharacterEllipsis'/><TextBlock Text='{Binding Sciezka}' FontSize='10' Foreground='#8294B0' TextTrimming='CharacterEllipsis'/></StackPanel></DataTemplate>");lista.Columns.Add(new DataGridTemplateColumn {Header=WidokDuplikatow()?"ZAWARTOŚĆ / SHA-256":"NAZWA / ŚCIEŻKA",CellTemplate=szablon,Width=new DataGridLength(1,DataGridLengthUnitType.Star),MinWidth=180});DodajKolumne(WidokDuplikatow()?"ROZMIAR PLIKU":"ROZMIAR","RozmiarTekst",118);if(WidokDuplikatow()){DodajKolumne("LOKALIZACJE","PlikiTekst",90);DodajKolumne("KOPIE ŁĄCZNIE","ZajeteTekst",110);DodajKolumne("POTENCJAŁ","PotencjalTekst",110);}else{DodajKolumne("TYP","TypTekst",115);DodajKolumne("FORMAT","Rozszerzenie",75);DodajKolumne("UTWORZONO","UtworzenieTekst",110);DodajKolumne("MODYFIKACJA","DataTekst",140);DodajKolumne("LOKALIZACJA","Sciezka",280);DodajKolumne("DUPLIKAT","StatusDuplikatu",140);DodajKolumne("TAGI","Oznaczenia",240);}lista.ToolTip="Szczegóły i oznaczenia są w prawym panelu.";}
    void DodajKolumne(string naglowek,string pole,double szerokosc){lista.Columns.Add(new DataGridTextColumn {Header=naglowek,Binding=new Binding(pole),Width=szerokosc,CanUserSort=false});}
    List<Wiersz> PobierzSurowe(string wybranyTryb,string wybranyFolder,string filtr,bool pokaz,int numerStrony,int limit){using(var baza=new Baza(Program.Indeks,false)){
        var args=new List<object>();string sql;
        if(wybranyTryb=="Potwierdzone duplikaty"||wybranyTryb=="Potencjalnie odzyskiwane miejsce"){sql="SELECT id,sha256,rozmiar,lokalizacje,niezalezne,zajete,potencjal,niepewne FROM grupy_duplikatow WHERE (?='' OR sha256 LIKE ? OR EXISTS(SELECT 1 FROM lokalizacje_duplikatow l WHERE l.grupa=grupy_duplikatow.id AND l.sciezka LIKE ?)) ORDER BY potencjal DESC,id LIMIT ? OFFSET ?";return baza.Zapytaj(sql,filtr,"%"+filtr+"%","%"+filtr+"%",limit+1,numerStrony*limit).Select(Program.Grupa).ToList();}
