    public static void Oczekuj(Func<bool> warunek){var zegar=Stopwatch.StartNew();while(!warunek()){if(zegar.Elapsed.TotalSeconds>30)throw new TimeoutException("Widok nie został wczytany.");var ramka=new DispatcherFrame();Dispatcher.CurrentDispatcher.BeginInvoke(DispatcherPriority.Background,new Action(()=>ramka.Continue=false));Dispatcher.PushFrame(ramka);Thread.Sleep(10);}}
    public static void Renderuj(Window okno,string sciezka){
        okno.ShowActivated=false;okno.ShowInTaskbar=false;okno.Opacity=0;okno.WindowStyle=WindowStyle.None;
        if(!okno.IsVisible)okno.Show();
        var zawartosc=(FrameworkElement)okno.Content;var panel=zawartosc as Panel;if(panel!=null)panel.Background=okno.Background;
        for(int i=0;i<4;i++){okno.UpdateLayout();var ramka=new DispatcherFrame();Dispatcher.CurrentDispatcher.BeginInvoke(DispatcherPriority.ApplicationIdle,new Action(()=>ramka.Continue=false));Dispatcher.PushFrame(ramka);}
        int szerokosc=(int)Math.Ceiling(zawartosc.ActualWidth),wysokosc=(int)Math.Ceiling(zawartosc.ActualHeight);
        var obraz=new RenderTargetBitmap(szerokosc,wysokosc,96,96,PixelFormats.Pbgra32);obraz.Render(zawartosc);var koder=new PngBitmapEncoder();koder.Frames.Add(BitmapFrame.Create(obraz));using(var plik=File.Create(sciezka))koder.Save(plik);
    }

