    public Window Okno;List<string> lokalizacje;string hash;long rozmiar;int zaladowane;
    public Porownanie(List<string> sciezki,string skrot,long bajty){lokalizacje=sciezki;hash=skrot;rozmiar=bajty;Okno=new Window {Title="Porównaj lokalizacje — Mapa dysków",Width=1380,Height=780,MinWidth=950,MinHeight=550,Background=Program.Kolor("#11151D"),Foreground=Brushes.White,FontFamily=new FontFamily("Segoe UI"),WindowStartupLocation=WindowStartupLocation.CenterOwner};Okno.Resources=Program.Zasoby;var uklad=new Grid {Margin=new Thickness(20),Background=Program.Kolor("#11151D")};uklad.RowDefinitions.Add(new RowDefinition {Height=GridLength.Auto});uklad.RowDefinitions.Add(new RowDefinition());Okno.Content=uklad;var opis=Program.Tekst("Porównanie lokalizacji  ·  "+Program.Rozmiar(bajty)+"  ·  SHA-256 "+skrot.Substring(0,16)+"…\nPodświetlone pliki należą do wybranej grupy. Foldery i pliki są przeglądane z indeksu, po 200 pozycji na stronę.",15,"#B5CBE9");uklad.Children.Add(opis);var strony=new Grid {Margin=new Thickness(0,15,0,0)};strony.ColumnDefinitions.Add(new ColumnDefinition());strony.ColumnDefinitions.Add(new ColumnDefinition {Width=new GridLength(18)});strony.ColumnDefinitions.Add(new ColumnDefinition());Grid.SetRow(strony,1);uklad.Children.Add(strony);var lewa=Panel("LEWA LOKALIZACJA",sciezki[0]);var prawa=Panel("PRAWA LOKALIZACJA",sciezki.Count>1?sciezki[1]:sciezki[0]);strony.Children.Add(lewa);Grid.SetColumn(prawa,2);strony.Children.Add(prawa);}
    FrameworkElement Panel(string nazwa,string poczatkowa){var panel=new Grid {Background=Program.Kolor("#181E28"),Margin=new Thickness(2)};panel.RowDefinitions.Add(new RowDefinition {Height=GridLength.Auto});panel.RowDefinitions.Add(new RowDefinition());panel.RowDefinitions.Add(new RowDefinition {Height=GridLength.Auto});var gora=new StackPanel {Margin=new Thickness(15)};panel.Children.Add(gora);gora.Children.Add(Program.Tekst(nazwa,11,"#8AA8D0"));var wybor=new ComboBox {ItemsSource=lokalizacje,SelectedItem=poczatkowa,IsEditable=true,Text=poczatkowa,Foreground=Brushes.Black};gora.Children.Add(wybor);var sciezka=new TextBox {Text=poczatkowa,IsReadOnly=true,TextWrapping=TextWrapping.Wrap,Background=Brushes.Transparent,Foreground=Program.Kolor("#E4EDFB"),BorderThickness=new Thickness(0)};gora.Children.Add(sciezka);var przyciski=new WrapPanel();gora.Children.Add(przyciski);var lista=new DataGrid {AutoGenerateColumns=false,IsReadOnly=true,CanUserAddRows=false,CanUserDeleteRows=false,EnableRowVirtualization=true,EnableColumnVirtualization=true,Background=Program.Kolor("#181E28"),Foreground=Program.Kolor("#E4EDFB"),RowBackground=Program.Kolor("#202C3C"),AlternatingRowBackground=Program.Kolor("#26364A"),HeadersVisibility=DataGridHeadersVisibility.Column,GridLinesVisibility=DataGridGridLinesVisibility.None,Margin=new Thickness(12),SelectionMode=DataGridSelectionMode.Single};VirtualizingPanel.SetVirtualizationMode(lista,VirtualizationMode.Recycling);lista.Columns.Add(new DataGridTextColumn {Header="Nazwa",Binding=new Binding("Nazwa"),Width=new DataGridLength(1,DataGridLengthUnitType.Star)});lista.Columns.Add(new DataGridTextColumn {Header="Rozmiar",Binding=new Binding("RozmiarTekst"),Width=110});lista.Columns.Add(new DataGridTextColumn {Header="Oznaczenie",Binding=new Binding("Oznaczenia"),Width=140});var styl=new Style(typeof(DataGridRow));var wyzwalacz=new DataTrigger {Binding=new Binding("Hash"),Value=hash};wyzwalacz.Setters.Add(new Setter(Control.BackgroundProperty,Program.Kolor("#255176")));styl.Triggers.Add(wyzwalacz);lista.RowStyle=styl;Grid.SetRow(lista,1);panel.Children.Add(lista);int strona=0,wersja=0;string folder=poczatkowa;var dol=new WrapPanel {Margin=new Thickness(12)};var numer=Program.Tekst("",12,"#A5BFDF");Grid.SetRow(dol,2);panel.Children.Add(dol);Button dalej=null,wstecz=null;
        Action<string> wczytaj=async f=>{folder=f;sciezka.Text=f;int aktualna=++wersja,n=strona;var dane=await Task.Run(()=>{using(var baza=new Baza(Program.Indeks,false)){var wynik=new List<Wiersz>();long liczbaFolderow=Convert.ToInt64(baza.Wartosc("SELECT count(*) FROM widok_folderow WHERE rodzic=?",f));
foreach(var r in baza.Zapytaj("SELECT "+Program.KolumnyFolderu+" FROM widok_folderow WHERE rodzic=? ORDER BY nazwa LIMIT 201 OFFSET ?",f,n*200))wynik.Add(Program.Folder(r));
if(wynik.Count<201){int miejsce=201-wynik.Count;long odPlikow=Math.Max(0,n*200-liczbaFolderow);foreach(var r in baza.Zapytaj("SELECT sciezka,rozmiar,zmiana,typ,sha256 FROM pliki WHERE folder=? ORDER BY CASE WHEN sha256=? THEN 0 ELSE 1 END,sciezka LIMIT ? OFFSET ?",f,hash,miejsce,odPlikow))wynik.Add(Program.Plik(r));}
return wynik;}});if(aktualna!=wersja)return;lista.ItemsSource=dane.Take(200).ToList();dalej.IsEnabled=dane.Count>200;wstecz.IsEnabled=n>0;numer.Text="Strona "+(n+1)+" • foldery i pliki";zaladowane++;};
        przyciski.Children.Add(Program.Przycisk("Otwórz folder",()=>{strona=0;wczytaj(wybor.Text);}));przyciski.Children.Add(Program.Przycisk("Eksplorator Windows",()=>Program.Eksplorator(folder)));przyciski.Children.Add(Program.Przycisk("Kopiuj ścieżkę",()=>Program.Kopiuj(folder)));przyciski.Children.Add(Program.Przycisk("↑",()=>{var rodzic=Path.GetDirectoryName(folder.TrimEnd('\\'));if(!String.IsNullOrEmpty(rodzic)){if(rodzic.EndsWith(":"))rodzic+="\\";strona=0;wczytaj(rodzic);}}));wstecz=Program.Przycisk("‹",()=>{strona--;wczytaj(folder);});dalej=Program.Przycisk("›",()=>{strona++;wczytaj(folder);});dol.Children.Add(wstecz);dol.Children.Add(numer);dol.Children.Add(dalej);wybor.SelectionChanged+=(s,e)=>{if(wybor.SelectedItem!=null){strona=0;wczytaj(Convert.ToString(wybor.SelectedItem));}};lista.MouseDoubleClick+=(s,e)=>{var w=lista.SelectedItem as Wiersz;if(w!=null&&w.Rodzaj=="folder"){strona=0;wczytaj(w.Sciezka);}};Action<string,string> zmianaNazwy=(stara,nowa)=>{folder=OperacjePlikowe.Podmien(folder,stara,nowa);lokalizacje=lokalizacje.Select(p=>OperacjePlikowe.Podmien(p,stara,nowa)).ToList();wybor.ItemsSource=lokalizacje;wybor.SelectedItem=folder;wybor.Text=folder;wczytaj(folder);};OperacjePlikowe.ZmienionoNazwe+=zmianaNazwy;Okno.Closed+=(s,e)=>OperacjePlikowe.ZmienionoNazwe-=zmianaNazwy;wczytaj(poczatkowa);return panel;}
    public void WczytajDoTestu(){OknoGlowne.Oczekuj(()=>zaladowane>=2);}
}
